            contentArea.classList.toggle('collapsed');
            toggleIcon.classList.toggle('collapsed');
        });

        if (!dataContainer || !contentArea) return;

        function parseData(text) {
            const data = { config: {}, scene: {}, characters: [], options: {} };
            const configMatch = text.match(/config:\s*([\s\S]*?)(?=\n\[)/);
            if (configMatch) {
                configMatch[1].trim().split('\n').forEach(line => {
