                    const parts = line.match(/^([^:]+):\s*(.*)/);
                    if (parts) items[parts[1].trim()] = parts[2].trim();
                });

                if (blockName.startsWith('角色状态_')) {
                    const charName = blockName.replace('角色状态_', '');
                    items.id = charName;
                    data.characters.push(items);
                } else if (blockName.startsWith('行动选项_')) {
                    data.options = items;
                } else if (blockName === '场景信息') {
                    data.scene = items;
                }
            }
            return data;
