                html += `<div class="options-block-title">你的选择是？(点击选项可直接复制)</div>`;
                for (const key in data.options) {
                    const fullText = data.options[key];
                    const cleanText = fullText.replace(/^\d+\.\s*/, '');
                    // 使用 data-index 而不是直接存储文本，避免 HTML 转义问题
                    html += `<div class="action-option" data-option-key="${key}">${fullText}</div>`;
                }
            }

            contentArea.innerHTML = html;

            // 添加点击事件监听器
            document.querySelectorAll('.action-option').forEach(option => {
                option.addEventListener('click', () => {
                    const optionKey = option.getAttribute('data-option-key');
                    const fullText = data.options[optionKey];
                    const textToCopy = fullText.replace(/^\d+\.\s*/, '');

                    // 优先使用 clipboard API，降级到 execCommand
                    if (navigator.clipboard && navigator.clipboard.writeText) {
                        navigator.clipboard.writeText(textToCopy).then(() => {
                            showToast('已复制！请粘贴到输入框发送');
                        }).catch(err => {
                            console.error('Clipboard API 失败: ', err);
                            fallbackCopy(textToCopy);
                        });
                    } else {
                        fallbackCopy(textToCopy);
                    }
                });
            });
        }

        function renderDataItem(label, value, icon = '') {
            if (!value || value === '待定' || value === '无') return '';
            return `
            <div class="data-item">
                <span class="data-key">${icon} ${label}:</span>
                <span class="data-value">${value}</span>
            </div>`;
        }

        const rawData = dataContainer.textContent.trim();
        if (rawData) {
            const parsedData = parseData(rawData);
            renderData(parsedData);
        }
    });
    </script>
